"use strict";(self.webpackChunktexlyre=self.webpackChunktexlyre||[]).push([["7099"],{6409(e,n,a){a.r(n),a.d(n,{metadata:()=>t,default:()=>p,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"latex-compilation/fonts","title":"Fonts","description":"TeXlyre can use fonts from the TeX Live distribution without bundling the full font collection in the browser. When a TeX Live font is not available locally, BusyTeX resolves it through prebuilt font metadata and fetches the required font file from the TeX Live server.","source":"@site/docs/latex-compilation/fonts.md","sourceDirName":"latex-compilation","slug":"/latex-compilation/fonts","permalink":"/docs/latex-compilation/fonts","draft":false,"unlisted":false,"editUrl":"https://github.com/texlyre/docs/tree/main/docs/latex-compilation/fonts.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3},"sidebar":"tutorialSidebar","previous":{"title":"Bibliographies","permalink":"/docs/latex-compilation/bibliographies"},"next":{"title":"Accessibility","permalink":"/docs/latex-compilation/accessibility"}}'),i=a(4848),s=a(8453);let r={sidebar_position:3},o="Fonts",l={},c=[{value:"TeX Live Fonts",id:"tex-live-fonts",level:2},{value:"Multilingual Typesetting",id:"multilingual-typesetting",level:2},{value:"Hyphenation and Line Breaking",id:"hyphenation-and-line-breaking",level:2},{value:"Project Fonts",id:"project-fonts",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",p:"p",pre:"pre",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"fonts",children:"Fonts"})}),"\n",(0,i.jsx)(n.p,{children:"TeXlyre can use fonts from the TeX Live distribution without bundling the full font collection in the browser. When a TeX Live font is not available locally, BusyTeX resolves it through prebuilt font metadata and fetches the required font file from the TeX Live server."}),"\n",(0,i.jsx)(n.h2,{id:"tex-live-fonts",children:"TeX Live Fonts"}),"\n",(0,i.jsxs)(n.p,{children:["XeLaTeX and LuaLaTeX can select TeX Live OpenType and TrueType fonts by name with ",(0,i.jsx)(n.code,{children:"fontspec"}),". Different families can be combined for display text, body copy, interface-like labels, and monospaced details:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-latex",metastring:"engine=lualatex pdfheight=520",children:"\\documentclass{article}\n\\usepackage[a4paper,margin=28mm]{geometry}\n\\usepackage{fontspec}\n\\usepackage{xcolor}\n\n\\setmainfont{Libertinus Serif}\n\\setsansfont{Fira Sans}\n\\setmonofont{Fira Mono}\n\\newfontfamily\\displayfont{Alegreya}\n\n\\definecolor{midnight}{HTML}{24344D}\n\\definecolor{coral}{HTML}{C75B4B}\n\\definecolor{teal}{HTML}{337C7A}\n\\definecolor{gold}{HTML}{B48732}\n\n\\setlength{\\parindent}{0pt}\n\\begin{document}\n{\\sffamily\\bfseries\\small\\addfontfeatures{LetterSpace=8}\\color{coral}\nFIELD NOTES / SERIES 04}\\par\n\\smallskip\n{\\displayfont\\fontsize{30}{31}\\selectfont\\color{midnight}\nSignals after rain}\\par\n\\medskip\n{\\color{teal}\\rule{\\linewidth}{1.2pt}}\\par\n\\medskip\n\nThe instruments were quiet until the afternoon shower passed. Then the glass roof brightened, the humidity trace rose, and a sequence of small observations began to form a readable pattern.\n\n\\medskip\n{\\sffamily\\bfseries\\color{gold}DETAIL}\\quad\n\\textsc{Small capitals} can label categories, \\textit{italic} can carry a softer note, and \\textbf{bold text} can mark a conclusion without changing the main typeface.\n\n\\medskip\n{\\ttfamily\\color{coral}station/reading-042.tex}\\par\n{\\sffamily\\small\\color{midnight}\nSerif for reading \\quad Sans for navigation \\quad Mono for technical details}\n\\end{document}\n"})}),"\n",(0,i.jsxs)(n.p,{children:["The fonts in this example come from TeX Live. ",(0,i.jsx)(n.code,{children:"xcolor"})," is independent of the font choice, so type families, weights, styles, and color can be combined like ordinary LaTeX formatting."]}),"\n",(0,i.jsx)(n.p,{children:"OpenType features can also be selected globally or changed for a small part of the document. For example, Alegreya provides old-style figures and small capitals, while lining and tabular figures are useful when numbers need to align:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-latex",metastring:"engine=lualatex pdfheight=500",children:"\\documentclass{article}\n\\usepackage[a4paper,margin=30mm]{geometry}\n\\usepackage{fontspec}\n\\usepackage{xcolor}\n\n\\setmainfont{Alegreya}[\n  Ligatures=TeX,\n  Numbers={OldStyle,Proportional}\n]\n\\setsansfont{Alegreya Sans}\n\\newfontfamily\\uifont{Fira Sans}\n\n\\definecolor{plum}{HTML}{6D4168}\n\\definecolor{leaf}{HTML}{4C7755}\n\\definecolor{orange}{HTML}{C7763C}\n\\definecolor{slate}{HTML}{34495E}\n\n\\setlength{\\parindent}{0pt}\n\\begin{document}\n{\\uifont\\bfseries\\small\\addfontfeatures{LetterSpace=10}\\color{leaf}\nTYPE SPECIMEN}\\par\n\\smallskip\n{\\fontsize{27}{29}\\selectfont\\bfseries\\color{plum}\nA cabinet of numbers}\\par\n\\medskip\n\nOld-style figures sit comfortably in prose: the archive contains 128 sketches from 7 sessions recorded during 2026. Small capitals can turn a short label such as \\textsc{field record} into quiet structure.\n\n\\bigskip\n{\\sffamily\\bfseries\\color{orange}LINING + TABULAR}\\par\n{\\addfontfeatures{Numbers={Lining,Tabular}}\\Large\n08:15\\quad 128.40\\quad 2026\\par\n08:45\\quad 129.05\\quad 2027}\n\n\\bigskip\n{\\color{slate}\\itshape\nItalic text can soften an annotation, while}\\par\n{\\sffamily\\bfseries\\color{plum}\\addfontfeatures{LetterSpace=5}\na tracked sans-serif label can sharpen the hierarchy.}\n\\end{document}\n"})}),"\n",(0,i.jsx)(n.p,{children:"pdfLaTeX uses the traditional TeX font mappings generated from the full TeX Live distribution, with missing font files fetched in the same way when required."}),"\n",(0,i.jsx)(n.h2,{id:"multilingual-typesetting",children:"Multilingual Typesetting"}),"\n",(0,i.jsxs)(n.p,{children:["Unicode engines can combine many languages and scripts in one document. Packages such as ",(0,i.jsx)(n.code,{children:"polyglossia"})," select language conventions and hyphenation patterns, while ",(0,i.jsx)(n.code,{children:"fontspec"})," can associate a suitable font with a particular script."]}),"\n",(0,i.jsx)(n.p,{children:"The example below deliberately uses wide margins to create a narrow text measure. Each paragraph is long enough for language-specific line breaking and hyphenation to become visible:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-latex",metastring:"engine=lualatex pdfheight=1050",children:"\\documentclass{article}\n\\usepackage[\n  a4paper,\n  left=46mm,\n  right=46mm,\n  top=24mm,\n  bottom=24mm\n]{geometry}\n\\usepackage{fontspec}\n\\usepackage{xcolor}\n\\usepackage{polyglossia}\n\n\\setdefaultlanguage{english}\n\\setotherlanguage{german}\n\\setotherlanguage{french}\n\\setotherlanguage{spanish}\n\\setotherlanguage{polish}\n\\setotherlanguage{finnish}\n\\setotherlanguage{russian}\n\\setotherlanguage{greek}\n\\setotherlanguage{arabic}\n\n\\setmainfont{Libertinus Serif}\n\\setsansfont{Fira Sans}\n\\newfontfamily\\greekfont[Script=Greek]{GFS Didot}\n\\newfontfamily\\russianfont[Script=Cyrillic]{Noto Serif}\n\\newfontfamily\\arabicfont[Script=Arabic]{Amiri}\n\\newfontfamily\\arabicfontsf[Script=Arabic]{Amiri}\n\n\\definecolor{ocean}{HTML}{356C88}\n\\definecolor{berry}{HTML}{8B4A63}\n\\definecolor{moss}{HTML}{4E7554}\n\\definecolor{amber}{HTML}{A66A2C}\n\n\\newcommand{\\langtitle}[2]{%\n  \\par\\medskip\n  {\\sffamily\\bfseries\\color{#1}#2}\\par\\nobreak\\smallskip}\n\n\\setlength{\\parindent}{0pt}\n\\setlength{\\parskip}{0.35em}\n\\hyphenpenalty=50\n\\exhyphenpenalty=50\n\n\\begin{document}\n{\\sffamily\\bfseries\\Large\\color{ocean}\nOne document, many languages}\\par\n\n\\langtitle{berry}{English}\nThe workshop notebook follows a small weather station beside the river, where changing temperatures, interchangeable instruments, and carefully documented calibration procedures create enough detail to test ordinary English hyphenation in a deliberately narrow column.\n\n\\begin{german}\n\\langtitle{moss}{Deutsch}\nIm Werkstatttagebuch wird eine kleine Messstation am Fluss beschrieben, deren Temperaturbeobachtungen, wiederverwendbare Messinstrumente und ausf\xfchrliche Kalibrierungsverfahren gen\xfcgend zusammengesetzte W\xf6rter enthalten, um die deutsche Silbentrennung in einer schmalen Textspalte sichtbar zu machen.\n\\end{german}\n\n\\begin{french}\n\\langtitle{amber}{Fran\xe7ais}\nLe carnet d\xe9crit un petit observatoire install\xe9 pr\xe8s de la rivi\xe8re, o\xf9 des instruments interchangeables, des v\xe9rifications m\xe9thodiques et une documentation soigneusement r\xe9dig\xe9e offrent suffisamment de mots pour montrer la coupure fran\xe7aise dans une colonne volontairement \xe9troite.\n\\end{french}\n\n\\begin{spanish}\n\\langtitle{ocean}{Espa\xf1ol}\nEl cuaderno describe una estaci\xf3n experimental junto al r\xedo, donde las observaciones meteorol\xf3gicas, los instrumentos intercambiables y los procedimientos de calibraci\xf3n cuidadosamente documentados permiten apreciar la separaci\xf3n sil\xe1bica del espa\xf1ol en una columna estrecha.\n\\end{spanish}\n\n\\begin{polish}\n\\langtitle{berry}{Polski}\nNotatnik opisuje niewielk\u0105 stacj\u0119 badawcz\u0105 nad rzek\u0105, w kt\xf3rej systematyczne obserwacje temperatury, wymienne przyrz\u0105dy pomiarowe oraz szczeg\xf3\u0142owo udokumentowane procedury kalibracyjne pozwalaj\u0105 zobaczy\u0107 polskie regu\u0142y dzielenia wyraz\xf3w w w\u0105skiej kolumnie tekstu.\n\\end{polish}\n\n\\begin{finnish}\n\\langtitle{moss}{Suomi}\nTy\xf6pajap\xe4iv\xe4kirja kuvaa joen rannalla toimivaa pient\xe4 havaintoasemaa, jossa l\xe4mp\xf6tilamittaukset, vaihdettavat tutkimusv\xe4lineet ja huolellisesti dokumentoidut kalibrointimenetelm\xe4t muodostavat riitt\xe4v\xe4n pitki\xe4 sanoja suomenkielisen tavutuksen havainnollistamiseen kapeassa palstassa.\n\\end{finnish}\n\n\\begin{russian}\n\\langtitle{amber}{\u0420\u0443\u0441\u0441\u043A\u0438\u0439}\n\u0412 \u0440\u0430\u0431\u043E\u0447\u0435\u043C \u0436\u0443\u0440\u043D\u0430\u043B\u0435 \u043E\u043F\u0438\u0441\u0430\u043D\u0430 \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0441\u0442\u0430\u043D\u0446\u0438\u044F \u0443 \u0440\u0435\u043A\u0438, \u0433\u0434\u0435 \u0440\u0435\u0433\u0443\u043B\u044F\u0440\u043D\u044B\u0435 \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u0438\u044F \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u044B, \u0432\u0437\u0430\u0438\u043C\u043E\u0437\u0430\u043C\u0435\u043D\u044F\u0435\u043C\u044B\u0435 \u043F\u0440\u0438\u0431\u043E\u0440\u044B \u0438 \u043F\u043E\u0434\u0440\u043E\u0431\u043D\u043E \u0437\u0430\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0435 \u043F\u0440\u043E\u0446\u0435\u0434\u0443\u0440\u044B \u043A\u0430\u043B\u0438\u0431\u0440\u043E\u0432\u043A\u0438 \u0441\u043E\u0437\u0434\u0430\u044E\u0442 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0434\u043B\u0438\u043D\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u044B \u0441\u043B\u043E\u0432 \u0432 \u0443\u0437\u043A\u043E\u0439 \u043A\u043E\u043B\u043E\u043D\u043A\u0435.\n\\end{russian}\n\n\\begin{greek}\n\\langtitle{ocean}{\u0395\u03BB\u03BB\u03B7\u03BD\u03B9\u03BA\u03AC}\n\u03A4\u03BF \u03B7\u03BC\u03B5\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03BF \u03C4\u03BF\u03C5 \u03B5\u03C1\u03B3\u03B1\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03C0\u03B5\u03C1\u03B9\u03B3\u03C1\u03AC\u03C6\u03B5\u03B9 \u03AD\u03BD\u03B1\u03BD \u03BC\u03B9\u03BA\u03C1\u03CC \u03C3\u03C4\u03B1\u03B8\u03BC\u03CC \u03C0\u03B1\u03C1\u03B1\u03C4\u03AE\u03C1\u03B7\u03C3\u03B7\u03C2 \u03B4\u03AF\u03C0\u03BB\u03B1 \u03C3\u03C4\u03BF \u03C0\u03BF\u03C4\u03AC\u03BC\u03B9, \u03CC\u03C0\u03BF\u03C5 \u03BF\u03B9 \u03C3\u03C5\u03C3\u03C4\u03B7\u03BC\u03B1\u03C4\u03B9\u03BA\u03AD\u03C2 \u03BC\u03B5\u03C4\u03C1\u03AE\u03C3\u03B5\u03B9\u03C2 \u03B8\u03B5\u03C1\u03BC\u03BF\u03BA\u03C1\u03B1\u03C3\u03AF\u03B1\u03C2, \u03C4\u03B1 \u03B5\u03BD\u03B1\u03BB\u03BB\u03AC\u03BE\u03B9\u03BC\u03B1 \u03CC\u03C1\u03B3\u03B1\u03BD\u03B1 \u03BA\u03B1\u03B9 \u03BF\u03B9 \u03C0\u03C1\u03BF\u03C3\u03B5\u03BA\u03C4\u03B9\u03BA\u03AC \u03BA\u03B1\u03C4\u03B1\u03B3\u03B5\u03B3\u03C1\u03B1\u03BC\u03BC\u03AD\u03BD\u03B5\u03C2 \u03B4\u03B9\u03B1\u03B4\u03B9\u03BA\u03B1\u03C3\u03AF\u03B5\u03C2 \u03B2\u03B1\u03B8\u03BC\u03BF\u03BD\u03CC\u03BC\u03B7\u03C3\u03B7\u03C2 \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03BF\u03CD\u03BD \u03B1\u03C1\u03BA\u03B5\u03C4\u03CC \u03BA\u03B5\u03AF\u03BC\u03B5\u03BD\u03BF \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C6\u03B1\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03BF \u03B5\u03BB\u03BB\u03B7\u03BD\u03B9\u03BA\u03CC\u03C2 \u03C3\u03C5\u03BB\u03BB\u03B1\u03B2\u03B9\u03C3\u03BC\u03CC\u03C2 \u03C3\u03B5 \u03C3\u03C4\u03B5\u03BD\u03AE \u03C3\u03C4\u03AE\u03BB\u03B7.\n\\end{greek}\n\n\\begin{Arabic}\n\\langtitle{berry}{\u0627\u0644\u0639\u0631\u0628\u064A\u0629}\n\u064A\u0635\u0641 \u062F\u0641\u062A\u0631 \u0627\u0644\u0648\u0631\u0634\u0629 \u0645\u062D\u0637\u0629 \u0631\u0635\u062F \u0635\u063A\u064A\u0631\u0629 \u0642\u0631\u0628 \u0627\u0644\u0646\u0647\u0631\u060C \u062D\u064A\u062B \u062A\u062C\u0645\u0639 \u0627\u0644\u0642\u064A\u0627\u0633\u0627\u062A \u0627\u0644\u0645\u0646\u062A\u0638\u0645\u0629 \u0644\u062F\u0631\u062C\u0629 \u0627\u0644\u062D\u0631\u0627\u0631\u0629 \u0648\u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062A\u0628\u062F\u064A\u0644 \u0648\u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0627\u0644\u0645\u0639\u0627\u064A\u0631\u0629 \u0627\u0644\u0645\u0648\u062B\u0642\u0629 \u0628\u0639\u0646\u0627\u064A\u0629 \u0646\u0635\u0627\u064B \u0637\u0648\u064A\u0644\u0627\u064B \u0628\u0645\u0627 \u064A\u0643\u0641\u064A \u0644\u0625\u0638\u0647\u0627\u0631 \u0643\u064A\u0641\u064A\u0629 \u062A\u0648\u0632\u064A\u0639 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0648\u0627\u0644\u0623\u0633\u0637\u0631 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u062F\u0627\u062E\u0644 \u0639\u0645\u0648\u062F \u0636\u064A\u0642.\n\\end{Arabic}\n\\end{document}\n"})}),"\n",(0,i.jsx)(n.p,{children:"The Latin-script paragraphs use Libertinus Serif, the Greek paragraph uses GFS Didot, Russian uses Noto Serif, and Arabic uses Amiri. Languages with hyphenation patterns use the rules selected for that language; scripts such as Arabic use their own shaping and line-breaking conventions."}),"\n",(0,i.jsx)(n.h2,{id:"hyphenation-and-line-breaking",children:"Hyphenation and Line Breaking"}),"\n",(0,i.jsxs)(n.p,{children:["Line breaking can be tuned independently of the selected language. For example, ",(0,i.jsx)(n.code,{children:"ragged2e"})," provides a ragged-right style that still permits hyphenation, while penalties can be used when hyphenation should be avoided:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-latex",metastring:"engine=lualatex pdfheight=580",children:"\\documentclass{article}\n\\usepackage[a4paper,margin=25mm]{geometry}\n\\usepackage{fontspec}\n\\usepackage{xcolor}\n\\usepackage{ragged2e}\n\n\\setmainfont{Libertinus Serif}\n\\setsansfont{Fira Sans}\n\\newfontfamily\\displayfont{Alegreya}\n\n\\definecolor{blue}{HTML}{356C88}\n\\definecolor{green}{HTML}{4E7554}\n\\definecolor{red}{HTML}{A34E4E}\n\n\\newcommand{\\sampletext}{%\nA flexible documentation system benefits from predictable typography, especially when interoperability requirements, configuration details, and unusually long technical terminology must remain readable inside narrow columns.}\n\n\\begin{document}\n{\\displayfont\\LARGE\\bfseries Three line-breaking styles}\\par\n\\medskip\n\n\\begin{minipage}[t]{0.29\\linewidth}\n{\\sffamily\\bfseries\\color{blue}Justified}\\par\\smallskip\n\\sampletext\n\\end{minipage}\n\\hfill\n\\begin{minipage}[t]{0.29\\linewidth}\n{\\sffamily\\bfseries\\color{green}Ragged + hyphenation}\\par\\smallskip\n\\RaggedRight\n\\sampletext\n\\end{minipage}\n\\hfill\n\\begin{minipage}[t]{0.29\\linewidth}\n{\\sffamily\\bfseries\\color{red}No hyphenation}\\par\\smallskip\n\\RaggedRight\n\\hyphenpenalty=10000\n\\exhyphenpenalty=10000\n\\sampletext\n\\end{minipage}\n\\end{document}\n"})}),"\n",(0,i.jsx)(n.p,{children:"These controls are ordinary TeX and LaTeX features; TeXlyre supplies the engine, packages, fonts, and language data needed to use them in the browser."}),"\n",(0,i.jsx)(n.h2,{id:"project-fonts",children:"Project Fonts"}),"\n",(0,i.jsx)(n.p,{children:"Custom fonts can be stored with the project and selected by file path. For example:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-latex",children:"\\usepackage{fontspec}\n\\setmainfont[Path=fonts/]{MyFont-Regular.otf}\n"})}),"\n",(0,i.jsx)(n.p,{children:"Project fonts remain part of the project and are not uploaded to the TeX Live server."}),"\n",(0,i.jsx)(n.p,{children:"Fonts installed only on the host operating system are not visible to the browser-based TeX engines."})]})}function p(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,a){a.d(n,{R:()=>r,x:()=>o});var t=a(6540);let i={},s=t.createContext(i);function r(e){let n=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);